export const PASSWORDS_ACCOUNTS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu kata sandi",q:"'Kata sandi' (password) adalah...",options:["Kunci rahasia berupa huruf/angka/simbol yang membuktikan bahwa kamu pemilik sah sebuah akun","Nama penggunamu","Sesuatu yang boleh diketahui semua orang"],answer:0,explain:"Kata sandi membuktikan identitas: hanya kamu (idealnya) yang tahu, jadi sistem percaya itu benar-benar kamu.",hint:"Kunci rahasia pembukti identitas, atau nama pengguna?"},
{n:2,type:"mcq",micro:"Kenapa kata sandi penting",q:"Kalau kata sandi akunmu diketahui orang lain, risikonya:",options:["Akunmu hanya jadi sedikit lebih lambat dibuka, tetapi isinya tidak bisa dibaca atau diubah orang lain","Mereka bisa masuk sebagai kamu, membaca pesan pribadimu, & bahkan mengubah/menghapus datamu","Risikonya kecil, karena orang lain yang tahu sandimu tetap tidak bisa masuk ke akun tanpa izin sistem"],answer:1,explain:"Kata sandi adalah pintu ke seluruh isi akun: pesan, foto, kontak, kadang uang. Menjaganya berarti menjaga semua itu.",hint:"Orang lain bisa masuk & mengubah data, atau tidak berisiko?"},
{n:3,type:"mcq",micro:"Kata sandi lemah",q:"Manakah kata sandi yang PALING LEMAH?",options:["T!m3&Bul4nG3lap#7q","Xk9#mL2$vQ8p","123456"],answer:2,explain:"'123456' adalah salah satu kata sandi paling umum di dunia & bisa ditebak dalam hitungan detik oleh program penebak.",hint:"Angka berurutan sederhana, atau kombinasi acak?"},
{n:4,type:"mcq",micro:"Ciri kata sandi kuat",q:"Kata sandi yang kuat umumnya...",options:["Panjang, memakai kombinasi huruf besar-kecil, angka, & simbol, serta tidak mudah ditebak","Pendek dan mudah diingat, misalnya empat huruf berurutan atau kata umum yang sering dipakai orang","Mirip dengan nama penggunamu ditambah tanggal lahir, supaya mudah diingat oleh dirimu dan temanmu"],answer:0,explain:"Panjang & keberagaman karakter membuat kemungkinan tebakan meledak jumlahnya, sehingga sangat sulit ditebak program.",hint:"Panjang & beragam karakter, atau pendek & sama dengan nama?"},
{n:5,type:"mcq",micro:"Hindari info pribadi",q:"Kenapa sebaiknya tidak memakai tanggal lahir atau nama sendiri sebagai kata sandi?",options:["Info itu terlalu panjang sehingga kolom kata sandi tidak muat dan sistem menolak menyimpannya","Info itu sering mudah diketahui orang lain (media sosial, KTP) sehingga mudah ditebak","Info itu terlalu sulit diingat pemiliknya sendiri, jadi lebih baik memakai kata yang tidak kamu kenal"],answer:1,explain:"Penjahat siber sering mencoba info yang mudah dicari tentang targetnya lebih dulu, seperti nama, tanggal lahir, nama hewan peliharaan.",hint:"Mudah diketahui orang lain, atau terlalu sulit diingat?"},
{n:6,type:"mcq",micro:"Panjang mengalahkan rumit",q:"Antara kata sandi pendek yang rumit ('Xk9#p') & kalimat panjang yang sederhana ('KucingOranyeSuka7Ikan'), mana umumnya lebih kuat?",options:["Sandi pendek yang rumit lebih kuat, karena simbol aneh membuat mesin sulit menebak berapa pun panjangnya","Keduanya sama lemahnya, sebab panjang maupun simbol tidak memengaruhi seberapa sulit sandi ditebak","Kalimat panjang, karena panjang total lebih menentukan kekuatan daripada kerumitan simbol semata"],answer:2,explain:"Makin panjang kata sandi, makin banyak kemungkinan kombinasi yang harus dicoba program penebak, meski katanya sederhana.",hint:"Kalimat panjang, atau pendek rumit selalu menang?"},
{n:7,type:"mcq",micro:"Satu sandi untuk semua akun?",q:"Memakai kata sandi yang SAMA untuk semua akun berbahaya karena...",options:["Kalau satu akun bocor, semua akun lain yang memakai sandi sama ikut berisiko dibobol","Lebih mudah diingat, jadi lebih aman","Tidak ada bahayanya"],answer:0,explain:"Peretas yang mendapat satu kata sandi akan mencobanya di akun lain (email, media sosial, bank). Sandi unik membatasi kerusakan.",hint:"Satu bocor, semua ikut berisiko, atau lebih aman?"},
{n:8,type:"mcq",micro:"Menjaga kerahasiaan",q:"Sikap yang tepat terhadap kata sandimu sendiri:",options:["Ditulis di tempat yang bisa dilihat banyak orang, misalnya di papan tulis kelas, supaya kamu tidak pernah lupa lagi","Tidak dibagikan ke siapa pun, termasuk teman dekat, kecuali ke orang tua/wali dalam keadaan yang memang perlu","Boleh dibagikan ke siapa saja yang memintanya dengan sopan, termasuk orang asing di internet yang mengaku ingin membantu"],answer:1,explain:"Semakin banyak yang tahu, semakin besar peluang bocor, baik sengaja maupun tidak sengaja.",hint:"Rahasiakan, kecuali situasi tertentu dengan wali, atau bagikan bebas?"},
{n:9,type:"order",micro:"Membuat kata sandi baru",q:"Urutkan langkah membuat kata sandi baru yang baik untuk akun penting.",items:["Pikirkan frasa atau kalimat yang hanya bermakna bagimu, bukan info publik","Perpanjang & tambahkan variasi huruf besar/kecil, angka, simbol","Pastikan berbeda dari kata sandi akun lainmu","Simpan dengan aman (pengelola kata sandi atau catatan tersembunyi), jangan hanya mengandalkan ingatan"],answer:[0,1,2,3],explain:"Frasa pribadi → perkuat variasi → pastikan unik → simpan aman. Kekuatan & keunikan dulu, baru penyimpanan.",hint:"Memastikan keunikan sebelum atau sesudah menyimpannya?"},
{n:10,type:"mcq",micro:"Kata sandi & nama pengguna",q:"Beda 'nama pengguna' (username) dengan 'kata sandi':",options:["Keduanya harus dirahasiakan sama ketatnya, karena nama pengguna dan kata sandi punya fungsi yang persis sama di semua situs","Keduanya boleh diketahui semua orang, karena yang penting hanya satu kali masuk saja dan setelah itu semuanya sudah aman sepenuhnya","Nama pengguna mengidentifikasi 'siapa kamu' & sering tidak rahasia; kata sandi membuktikan itu benar-benar kamu & harus rahasia"],answer:2,explain:"Nama pengguna/email sering terlihat publik (mis. alamat email). Kata sandi adalah bagian yang wajib rahasia.",hint:"Nama pengguna publik, kata sandi rahasia, atau keduanya sama?"},
{n:11,type:"tf",micro:"Kata sandi umum mudah ditebak",q:"Benar atau Salah: Kata sandi yang sangat umum dipakai banyak orang (seperti 'password', '123456', 'qwerty') termasuk yang pertama dicoba oleh program penebak kata sandi.",answer:true,explain:"Program penebak sering memakai daftar kata sandi paling umum lebih dulu karena peluang berhasilnya tinggi.",hint:"Termasuk yang pertama dicoba, atau paling sulit ditebak?"},
{n:12,type:"tf",micro:"Kata sandi tak pernah perlu diganti?",q:"Benar atau Salah: Sekali membuat kata sandi yang kuat, kamu tidak perlu pernah menggantinya lagi seumur hidup.",answer:false,explain:"Sebaliknya, kata sandi perlu diganti bila ada tanda kebocoran (mis. layanan diretas, ada aktivitas aneh), meski sandi itu sendiri kuat.",hint:"Tidak perlu diganti, atau perlu diganti bila ada tanda kebocoran?"},
{n:13,type:"mcq",micro:"Menghindari pola yang jelas",q:"Kata sandi 'Aa123456!' terlihat memenuhi syarat (huruf besar, kecil, angka, simbol) tapi tetap lemah karena...",options:["Polanya (huruf-angka berurutan) sangat umum & mudah ditebak, meski 'terlihat' rumit","Terlalu panjang","Tidak ada simbol"],answer:0,explain:"Memenuhi 'ceklis' jenis karakter tidak cukup kalau polanya mudah ditebak. Keacakan sesungguhnya yang penting.",hint:"Pola umum yang mudah ditebak, atau terlalu panjang?"},
{n:14,type:"mcq",micro:"Mengingat banyak kata sandi",q:"Cara realistis mengelola banyak kata sandi berbeda untuk banyak akun:",options:["Tulis semua kata sandi di kertas tempel dan tempel di depan layar komputer, supaya cepat terlihat setiap kali butuh login","Pakai pengelola kata sandi (password manager) atau sistem pribadi yang aman untuk mencatatnya, bukan mengandalkan ingatan semata","Pakai kata sandi yang sama persis untuk semua akun, supaya hanya satu yang perlu diingat dan tidak ada yang tertukar"],answer:1,explain:"Manusia sulit mengingat puluhan sandi unik. Alat pengelola yang tepercaya menyimpannya dengan aman & terenkripsi.",hint:"Pakai pengelola kata sandi, atau sama semua / tempel di layar?"},
{n:15,type:"mcq",micro:"Kata sandi & privasi orang lain",q:"Kalau kamu tahu kata sandi teman/keluarga (mis. diberi tahu untuk keperluan tertentu), sikap yang tepat:",options:["Boleh dipakai kapan saja untuk keperluan lain karena kamu sudah tahu, sebab pemberitahuan itu izin umum","Bagikan ke teman-teman lain supaya bisa dipakai bersama, sebab satu kata sandi cukup untuk banyak orang","Jangan memakainya untuk hal lain di luar yang diizinkan, & jangan membagikannya ke orang lain"],answer:2,explain:"Dipercaya tahu kata sandi bukan izin memakainya sesuka hati. Menghormati batas kepercayaan itu penting.",hint:"Jangan disalahgunakan/dibagikan, atau bebas dipakai?"},
{n:16,type:"tf",micro:"Kata sandi pendek cukup untuk akun tidak penting?",q:"Benar atau Salah: Akun 'kecil' yang terasa tidak penting boleh diberi kata sandi lemah karena tidak mungkin jadi celah ke mana pun.",answer:false,explain:"Sebaliknya, akun forum kecil yang dipakai email sama dengan akun pentingmu tetap bisa jadi celah, terutama bila kata sandinya dipakai ulang. Semua akun layak kata sandi yang cukup kuat.",hint:"Semua akun layak sandi kuat, atau akun kecil boleh sandi lemah?"},
{n:17,type:"mcq",micro:"Membuat kata sandi mudah diingat & kuat",q:"Teknik 'kalimat acak' untuk kata sandi: pilih 4 kata acak yang tidak berhubungan (mis. 'Gitar-Awan7-Sepatu!-Danau') karena...",options:["Panjang & sulit ditebak mesin, tapi tetap bisa diingat manusia lewat gambaran mental","Lebih pendek daripada kata sandi biasa, sehingga mesin pencoba sandi cepat menyerah menebaknya","Lebih mudah ditebak mesin daripada satu kata tunggal, karena kata acak ada di kamus sandi umum"],answer:0,explain:"Kombinasi kata acak yang panjang sulit bagi komputer untuk menebak, tapi otak manusia bisa membuat cerita untuk mengingatnya.",hint:"Panjang & mudah diingat manusia, atau selalu lebih pendek?"},
{n:18,type:"mcq",micro:"Kata sandi di tempat umum",q:"Mengetik kata sandi saat orang lain bisa melihat layar/tanganmu (di angkot, warnet) sebaiknya...",options:["Aman dilakukan di angkot yang ramai, karena orang di sekitarmu jarang memperhatikan layarmu","Dihindari atau ditutupi pandangan, karena orang bisa 'mengintip bahu' (shoulder surfing)","Tidak masalah di tempat ramai, karena orang lain tidak peduli dan tidak berniat memanfaatkan sandimu"],answer:1,explain:"'Mengintip bahu' adalah cara sederhana tapi efektif mencuri kata sandi. Sadari sekitarmu saat mengetiknya.",hint:"Hindari/tutupi, atau tidak masalah?"},
{n:19,type:"mcq",micro:"Kata sandi & akun bersama",q:"Untuk akun yang benar-benar dipakai bersama keluarga (mis. akun streaming keluarga), praktik yang wajar:",options:["Bagikan kepada yang memintanya, termasuk teman jauh yang ingin ikut menonton, karena akun keluarga boleh dipakai umum","Akun keluarga tidak butuh kata sandi, karena anggota rumah sudah saling percaya dan saling kenal baik","Kata sandinya disepakati & dijaga hanya di antara anggota keluarga itu, tetap tidak dibagikan ke luar"],answer:2,explain:"Akun bersama tetap butuh batas: 'bersama' berarti antar anggota yang disepakati, bukan terbuka untuk semua orang.",hint:"Dijaga di antara yang disepakati, atau dibagikan bebas?"},
{n:20,type:"open",micro:"Buat & jelaskan kata sandi kuat",q:"Buat contoh kata sandi kuat untuk akun email (JANGAN gunakan kata sandi asli akunmu, buat contoh fiktif). Jelaskan: (a) kata sandinya (contoh, boleh disamarkan sebagian), (b) kenapa itu kuat (sebutkan minimal 3 alasan teknis), (c) teknik yang kamu pakai untuk membuatnya mudah kamu ingat, (d) satu kesalahan umum yang berhasil kamu hindari.",explain:"Jawaban baik: contoh kata sandi yang benar-benar panjang & beragam (bukan sekadar menambah '!' di kata umum), minimal 3 alasan teknis yang benar (panjang, tidak ada di kamus, tidak berhubungan data pribadi, tidak berpola), teknik mengingat yang masuk akal (asosiasi/cerita), & satu kesalahan umum yang disebut & dihindari secara spesifik.",hint:"Pastikan alasan (b) menyebut hal teknis nyata (panjang, keacakan, tidak di kamus), bukan hanya 'karena sulit dibaca'.",sample:"(a) Contoh kata sandi (bukan asli): 'BiruLangit-9Kuda!Berlari'. (b) Kenapa kuat: (1) panjangnya 24 karakter, jauh melebihi minimum umum 8 karakter, membuat kemungkinan kombinasi sangat besar; (2) menggabungkan huruf besar-kecil, angka, & simbol secara alami, bukan sekadar 'A' di depan & '!' di belakang; (3) bukan kata/kalimat yang bisa ditemukan di kamus atau berhubungan dengan data pribadiku (bukan nama, tanggal lahir, atau nama sekolah); (4) tidak memakai pola berurutan seperti 'abc' atau '123'. (c) Teknik mengingat: aku membayangkan sebuah cerita aneh, 'langit biru tempat 9 ekor kuda berlari', gambar itu membantu aku mengingat urutan kata tanpa menuliskannya di mana pun. (d) Kesalahan yang kuhindari: aku tidak memakai nama peliharaanku ('Milo123!') yang mudah ditebak orang yang mengenalku dari media sosial, & aku tidak memakai kata sandi ini di akun lain manapun, setiap akun pentingku punya kata sandi berbeda dengan tema cerita yang berbeda pula."},
{n:21,type:"classify",micro:"Kebiasaan aman vs berisiko soal kata sandi",q:"Kelompokkan tiap kebiasaan ke 'Aman' atau 'Berisiko'.",items:["Memakai kata sandi berbeda untuk tiap akun penting","Menuliskan kata sandi di catatan tempel di layar komputer","Menyalakan verifikasi dua langkah di akun email","Memakai nama & tanggal lahir sendiri sebagai kata sandi"],groups:["Aman","Berisiko"],answer:{"Aman":["Memakai kata sandi berbeda untuk tiap akun penting","Menyalakan verifikasi dua langkah di akun email"],"Berisiko":["Menuliskan kata sandi di catatan tempel di layar komputer","Memakai nama & tanggal lahir sendiri sebagai kata sandi"]},explain:"Aman: unik per akun, lapisan tambahan (2FA). Berisiko: terlihat siapa saja, mudah ditebak dari info pribadi.",hint:"Menambah lapisan keamanan, atau mudah dilihat/ditebak?"},
{n:22,type:"mcq",micro:"Verifikasi dua langkah (2FA)",q:"'Verifikasi dua langkah' (2FA) menambah keamanan dengan cara...",options:["Meminta bukti kedua (mis. kode dari HP) selain kata sandi, sehingga sandi saja tidak cukup untuk masuk","Meminta kata sandi diketik dua kali berturut-turut, supaya salah ketik tercegah dan akun lebih aman","Membuat login dua kali lebih lambat tanpa manfaat keamanan, karena langkah kedua hanya menambah waktu tunggu"],answer:0,explain:"Bahkan kalau kata sandimu bocor, peretas masih butuh 'bukti kedua' (kode SMS, aplikasi autentikasi) yang biasanya hanya ada di perangkatmu.",hint:"Bukti kedua selain sandi, atau mengetik sandi dua kali?"},
{n:23,type:"mcq",micro:"Kenapa 2FA penting",q:"2FA sangat berguna untuk akun penting (email utama, akun bank) karena...",options:["Hanya berguna untuk akun media sosial, sedangkan email utama dan akun bank sudah cukup dengan satu kata sandi","Email utama sering jadi 'pintu pemulihan' semua akun lain; melindunginya melindungi banyak hal sekaligus","Tidak berguna untuk email, karena email hanya dipakai menerima pesan dan tidak terkait dengan akun lain"],answer:1,explain:"Kalau email utamamu dibobol, peretas bisa mereset kata sandi akun lain lewat email itu. Melindunginya adalah prioritas tinggi.",hint:"Email = pintu pemulihan banyak akun, atau tak berguna?"},
{n:24,type:"mcq",micro:"Kode 2FA jangan dibagikan",q:"Seseorang menelepon mengaku dari 'layanan bank/aplikasi' & meminta kode 2FA yang baru saja kamu terima. Sikap yang benar:",options:["Berikan kodenya karena mereka menyebut nama layanan resmi dan suaranya terdengar yakin dan sopan","Berikan sebagian kode saja, misalnya tiga angka pertama, supaya mereka percaya tetapi sisanya aman","Tolak & jangan berikan; layanan resmi tidak pernah meminta kode 2FA lewat telepon/pesan"],answer:2,explain:"Kode 2FA adalah 'kunci kedua' pribadimu. Siapa pun yang memintanya lewat telepon/pesan hampir pasti penipu.",hint:"Tolak & jangan beri, atau beri karena mengaku resmi?"},
{n:25,type:"mcq",micro:"Pertanyaan keamanan",q:"'Pertanyaan keamanan' (mis. 'nama hewan peliharaan pertamamu?') untuk pemulihan akun sebaiknya dijawab dengan...",options:["Jawaban yang tidak mudah ditemukan orang lain, bisa jadi jawaban 'palsu' yang hanya kamu ingat, bukan fakta yang bisa dicari di media sosial","Jawaban jujur dan apa adanya selalu, karena jawaban yang benar adalah yang paling mudah diingat dan memang paling aman dipakai","Jawaban yang sama persis untuk semua situs, supaya tidak lupa, sehingga satu jawaban yang bocor pun tidak akan memengaruhi akun lain"],answer:0,explain:"Info seperti nama hewan peliharaan sering ada di media sosial. Memakai jawaban buatan sendiri yang tidak bisa ditebak lebih aman.",hint:"Jawaban buatan yang tidak bisa ditebak, atau jujur apa adanya?"},
{n:26,type:"mcq",micro:"Email pemulihan",q:"Mengapa penting mengatur email/nomor pemulihan yang masih aktif untuk akun-akun penting?",options:["Hanya untuk menerima iklan dan promosi dari layanan itu, sehingga tidak ada kaitannya dengan pemulihan atau keamanan akunmu","Kalau lupa kata sandi atau akun bermasalah, itulah jalur resmi untuk membuktikan kamu pemiliknya & memulihkan akses","Tidak penting sama sekali, karena akun yang terkunci selalu bisa dibuka lagi otomatis tanpa perlu membuktikan bahwa kamu pemiliknya"],answer:1,explain:"Tanpa email/nomor pemulihan yang aktif, akun yang terkunci bisa sangat sulit atau bahkan tidak bisa dipulihkan.",hint:"Jalur resmi memulihkan akses, atau hanya untuk iklan?"},
{n:27,type:"tf",micro:"Pengelola kata sandi",q:"Benar atau Salah: Pengelola kata sandi (password manager) tepercaya menyimpan kata sandimu dalam bentuk teks biasa yang mudah dibaca siapa saja.",answer:false,explain:"Sebaliknya, pengelola kata sandi tepercaya menyimpan sandimu dalam bentuk terenkripsi & bahkan bisa membuatkan kata sandi acak yang kuat untukmu.",hint:"Terenkripsi & bisa buatkan sandi acak, atau tidak aman?"},
{n:28,type:"tf",micro:"Semua situs sama amannya?",q:"Benar atau Salah: Semua situs & aplikasi menyimpan kata sandimu dengan cara yang sama-sama aman.",answer:false,explain:"Sebaliknya, sebagian layanan punya praktik keamanan yang buruk (menyimpan sandi tanpa dienkripsi, dsb). Ini salah satu alasan penting memakai sandi unik per situs.",hint:"Semua sama aman, atau bervariasi & itu alasan sandi unik penting?"},
{n:29,type:"mcq",micro:"Tanda akun mungkin diretas",q:"Tanda-tanda akunmu mungkin sudah diretas:",options:["Tampilan aplikasinya berwarna berbeda dari biasanya setelah pembaruan, padahal kamu tidak melihat kegiatan lain yang aneh di akunmu","Akunmu memiliki banyak teman baru yang menyapa dan mengikuti, padahal tidak ada pesan atau login yang mencurigakan sama sekali","Ada aktivitas yang tidak kamu lakukan (pesan terkirim aneh, login dari lokasi asing, kata sandi berubah sendiri)"],answer:2,explain:"Aktivitas yang tidak kamu lakukan adalah sinyal kuat. Banyak layanan menampilkan riwayat login yang bisa diperiksa.",hint:"Aktivitas aneh yang bukan kamu, atau soal tampilan/jumlah teman?"},
{n:30,type:"order",micro:"Langkah saat akun mungkin diretas",q:"Urutkan langkah bila kamu curiga akunmu diretas.",items:["Segera ganti kata sandi akun itu (dari perangkat yang aman)","Nyalakan verifikasi dua langkah bila belum aktif","Periksa & cabut sesi/perangkat lain yang login tapi bukan kamu","Beri tahu kontak dekat bila akun sempat mengirim pesan aneh atas namamu, & laporkan ke layanan bila perlu"],answer:[0,1,2,3],explain:"Kunci pintu (ganti sandi) → tambah lapisan (2FA) → usir yang menyusup (sesi lain) → beri tahu & laporkan. Mengunci dulu, baru bersih-bersih.",hint:"Mengganti kata sandi sebelum atau sesudah memberi tahu kontak?"},
{n:31,type:"mcq",micro:"Mengunci sesi di perangkat lain",q:"Fitur 'keluar dari semua perangkat' pada akun berguna ketika...",options:["Kamu curiga seseorang masih login di perangkat lain tanpa izinmu, & ingin memutus akses itu sekaligus","Kamu ingin akun berjalan lebih cepat","Tidak ada gunanya"],answer:0,explain:"Fitur ini memutus semua sesi aktif, memaksa siapa pun (termasuk penyusup) login ulang dengan kata sandi barumu.",hint:"Memutus akses tak sah, atau mempercepat akun?"},
{n:32,type:"tf",micro:"Kata sandi & waktu",q:"Benar atau Salah: Kata sandi yang awalnya kuat akan tetap sama amannya selamanya, tidak peduli apa pun yang terjadi pada layanan yang memakainya.",answer:false,explain:"Sebaliknya, kebocoran data besar pada layanan lain (data breach) bisa mengekspos kata sandi (atau kombinasi email+sandi) walau kata sandi itu sendiri rumit. Karena itu penting diganti bila layananmu terkena kebocoran.",hint:"Bisa jadi tidak aman lagi karena kebocoran, atau kekuatannya tetap selamanya?"},
{n:33,type:"mcq",micro:"Memeriksa kebocoran data",q:"Beberapa layanan memungkinkan mengecek apakah emailmu pernah muncul dalam kebocoran data yang diketahui. Manfaatnya:",options:["Membuat akunmu otomatis lebih aman tanpa tindakan lain","Kamu tahu kapan harus segera mengganti kata sandi akun terkait","Tidak ada manfaatnya"],answer:1,explain:"Mengetahui adanya kebocoran adalah sinyal untuk bertindak (ganti sandi), bukan solusi otomatis itu sendiri.",hint:"Sinyal untuk bertindak, atau tak bermanfaat / otomatis aman?"},
{n:34,type:"mcq",micro:"Kata sandi di perangkat sekolah/umum",q:"Saat login di komputer sekolah/warnet, kebiasaan yang aman:",options:["Centang 'ingat saya' supaya login berikutnya lebih cepat dan praktis di komputer itu","Biarkan akun tetap login agar pengguna berikutnya bisa langsung memakainya, sebagai bentuk membantu","Jangan centang 'ingat saya'/'simpan kata sandi', & logout setelah selesai"],answer:2,explain:"Perangkat bersama berarti pengguna berikutnya bisa mengakses akunmu kalau kamu tidak logout & tidak menyimpan sandi di sana.",hint:"Jangan simpan sandi & selalu logout, atau simpan & biarkan login?"},
{n:35,type:"mcq",micro:"Autentikasi biometrik",q:"Sidik jari atau pemindaian wajah sebagai cara masuk (biometrik) itu...",options:["Praktis & cukup aman untuk perangkat pribadi, tapi biasanya tetap ada kata sandi cadangan sebagai jalur utama akun","Menggantikan kebutuhan kata sandi di semua tempat, sehingga akun tidak lagi punya sandi cadangan","Kurang aman dibanding kata sandi dalam keadaan apa pun, karena sidik jari dan wajah mudah ditiru orang yang melihatnya"],answer:0,explain:"Biometrik mengunci perangkat dengan nyaman, tapi akun daringmu (email, media sosial) tetap punya kata sandi sebagai dasar.",hint:"Praktis tapi sandi tetap ada sebagai dasar, atau menggantikan sepenuhnya?"},
{n:36,type:"mcq",micro:"Kata sandi anak & pengawasan orang tua",q:"Untuk anak-anak, berbagi sebagian info akun dengan orang tua/wali...",options:["Berarti harus dibagikan kepada orang dewasa di sekitar, termasuk tetangga dan orang asing, karena mereka ikut menjaga anak","Bisa masuk akal untuk keamanan & pengawasan yang wajar, sesuai kesepakatan keluarga, tanpa berarti membagikannya ke orang luar","Tidak boleh dalam kondisi apa pun, sekalipun keluarga sepakat dan tujuannya menjaga keselamatanmu di internet"],answer:1,explain:"Konteks keluarga berbeda dari berbagi ke publik. Kesepakatan yang jelas antara anak & wali tentang batasnya penting.",hint:"Bisa masuk akal dalam keluarga, atau selalu terlarang / harus ke semua orang?"},
{n:37,type:"tf",micro:"Kata sandi terkuat sekalipun butuh kerahasiaan",q:"Benar atau Salah: Selama sebuah kata sandi sangat kuat secara matematis, aman-aman saja membagikannya ke orang lain atau menuliskannya di tempat yang mudah dilihat.",answer:false,explain:"Sebaliknya, kekuatan matematis kata sandi percuma kalau kerahasiaannya bocor lewat cara lain, seperti dibagikan atau terlihat orang. Kata sandi tetap perlu dirahasiakan.",hint:"Tetap perlu dirahasiakan, atau kekuatannya saja cukup?"},
{n:38,type:"mcq",micro:"Login sosial (masuk dengan akun lain)",q:"'Masuk dengan Google/Facebook' di situs lain berarti...",options:["Kata sandimu dikirim langsung ke situs itu dan disimpan di sana, sehingga situs itu bisa memakainya di layanan lain tanpa bertanya lagi kepadamu","Cara ini lebih berbahaya daripada membuat akun baru di setiap situs, bagaimanapun keadaannya, sehingga sebaiknya dihindari","Situs itu memakai akun Google/Facebook-mu untuk verifikasi, jadi keamanan akun utamamu jadi makin penting; & situs itu tidak (biasanya) melihat kata sandi aslimu"],answer:2,explain:"Metode ini bisa praktis & menghindari membuat sandi baru, tapi berarti keamanan akun 'utama'-mu makin krusial untuk dijaga.",hint:"Memakai akun utama untuk verifikasi tanpa mengirim sandi asli, atau mengirim sandi langsung?"},
{n:39,type:"mcq",micro:"Kata sandi & tanggung jawab bersama",q:"Kalau kamu diberi akses sementara ke akun bersama (mis. akun sekolah/organisasi), tanggung jawabmu meliputi...",options:["Menjaga kerahasiaannya, tidak memakainya untuk hal di luar tujuan, & memberi tahu bila melihat sesuatu yang mencurigakan","Bebas memakainya untuk keperluan pribadi apa pun yang kamu inginkan, karena akses sementara berarti kamu sudah dianggap pemiliknya sepenuhnya","Membagikannya kepada teman-teman yang penasaran dan ingin mencoba, karena akun bersama memang boleh dipakai oleh siapa saja yang meminta"],answer:0,explain:"Akses bersama membawa tanggung jawab bersama. Menyalahgunakannya merugikan semua yang bergantung pada akun itu.",hint:"Jaga & pakai sesuai tujuan, atau bebas / bagikan?"},
{n:40,type:"open",micro:"Rencana keamanan akun",q:"Buat rencana keamanan untuk 3 akun pentingmu (mis. email, media sosial, akun sekolah). Untuk masing-masing, tulis: (a) apakah kata sandinya unik (tidak dipakai di akun lain), (b) apakah 2FA sudah aktif atau akan kamu aktifkan, (c) apakah email/nomor pemulihannya masih aktif & benar, (d) satu langkah yang akan kamu lakukan minggu ini untuk memperbaiki salah satu akun yang masih lemah.",explain:"Jawaban baik: menilai jujur ketiga akun pada empat kriteria (unik, 2FA, pemulihan aktif), mengenali dengan spesifik akun mana yang lemah & kenapa (bukan generik), & satu langkah perbaikan konkret yang bisa benar-benar dilakukan minggu ini.",hint:"Kalau semua akunmu 'sudah aman', pikirkan lagi lebih jujur, biasanya ada minimal satu titik lemah, seperti sandi yang dipakai ulang di layanan lama.",sample:"Akun 1, Email utama: (a) Kata sandinya unik, tidak dipakai di akun lain, dibuat dengan teknik kalimat acak. (b) 2FA sudah aktif lewat aplikasi autentikasi di HP. (c) Nomor pemulihan masih aktif, itu nomor HP-ku sendiri. Sudah cukup aman. Akun 2, Media sosial: (a) Ternyata kata sandinya sama dengan yang kupakai di sebuah forum game lama, ini masalah. (b) 2FA belum aktif. (c) Email pemulihannya benar & aktif. Perlu diperbaiki. Akun 3, Akun belajar daring sekolah: (a) Kata sandinya unik. (b) Tidak ada opsi 2FA di sistem sekolah ini. (c) Emailnya email sekolahku yang masih aktif. Cukup aman sejauh yang bisa kuatur. (d) Langkah minggu ini: aku akan segera mengganti kata sandi media sosialku jadi kata sandi baru yang unik (tidak dipakai di mana pun lagi), lalu menyalakan verifikasi dua langkah di akun itu karena media sosial adalah salah satu akun yang paling sering jadi sasaran."},
{n:41,type:"mcq",micro:"Teknik passphrase",q:"Membuat 'passphrase' (frasa sandi) dari 4-5 kata acak yang tidak berhubungan lebih baik daripada satu kata + angka karena...",options:["Tidak ada bedanya, karena jumlah kata dan jumlah kombinasi tidak memengaruhi lamanya mesin menebak sandi","Jumlah kombinasi yang harus dicoba mesin jauh lebih besar, sementara tetap mudah diingat lewat cerita atau gambaran","Kata acak lebih pendek daripada satu kata dengan angka, sehingga mesin penebak lebih cepat selesai"],answer:1,explain:"Empat kata acak dari kosakata besar menghasilkan kombinasi yang jauh lebih banyak daripada satu kata dengan sedikit variasi.",hint:"Kombinasi jauh lebih banyak & tetap mudah diingat, atau tak ada beda?"},
{n:42,type:"mcq",micro:"Menghindari kata sandi berpola situs",q:"Membuat variasi kecil dari satu kata sandi dasar untuk tiap situs (mis. 'Rahasia1Gmail', 'Rahasia1FB') berisiko karena...",options:["Aman, karena peretas jarang memperhatikan pola dan hanya mencoba kata acak satu per satu","Membuat semua sandi jadi lebih pendek sehingga lebih cepat diketik, itulah alasan variasi berisiko","Kalau satu sandi bocor & polanya terlihat, peretas bisa menebak variasi untuk situs lainmu"],answer:2,explain:"Pola yang jelas (kata dasar + nama situs) mudah dikenali & ditebak begitu satu sandi bocor. Sebaiknya benar-benar acak & berbeda.",hint:"Pola bisa ditebak dari satu kebocoran, atau tetap aman?"},
{n:43,type:"mcq",micro:"Menyimpan kata sandi dengan aman",q:"Cara menyimpan catatan kata sandi secara aman bila tidak memakai pengelola kata sandi digital:",options:["Kertas fisik yang disimpan di tempat aman & tersembunyi (bukan ditempel di layar), bukan file teks polos di komputer bersama","Simpan dalam berkas 'sandi.txt' di desktop komputer sekolah, karena komputer sekolah dijaga dan tidak dipakai orang","Tempel catatan di dinding kamar yang sering dilihat tamu, supaya anggota rumah mudah membantu mengingat"],answer:0,explain:"Kalau harus dicatat manual, kertas yang disimpan aman lebih baik daripada file digital yang mudah disalin & tersebar tanpa jejak.",hint:"Kertas di tempat tersembunyi, atau file digital di komputer bersama?"},
{n:44,type:"mcq",micro:"Mengganti kata sandi secara berkala vs saat perlu",q:"Pendekatan yang lebih efektif untuk kapan mengganti kata sandi:",options:["Jangan mengganti sama sekali sekalipun ada tanda kebocoran, karena kata sandi lama masih aman asal kamu belum lupa dan belum pernah membagikannya","Ganti saat ada tanda kebocoran atau kecurigaan, dengan kata sandi kuat & unik sejak awal, daripada mengganti rutin tanpa alasan dengan sandi yang mirip-mirip","Ganti setiap hari dengan sandi yang mirip-mirip dari hari sebelumnya, supaya terasa baru dan dianggap lebih aman"],answer:1,explain:"Mengganti terlalu sering tanpa alasan sering membuat orang memilih sandi yang lebih lemah/mirip karena lelah mengingat. Fokus pada kekuatan awal & respons cepat pada kebocoran.",hint:"Ganti saat ada tanda kebocoran, atau ganti tiap hari / tak pernah?"},
{n:45,type:"tf",micro:"Kunci layar juga penting",q:"Benar atau Salah: Mengunci layar perangkat (PIN/pola/biometrik) sama pentingnya dengan kata sandi akun, karena perangkat yang tidak terkunci membuka akses ke semua akun yang sudah login di dalamnya.",answer:true,explain:"Kalau perangkatmu tidak terkunci & hilang/dipinjam sembarangan, siapa pun bisa membuka semua akun yang sedang login tanpa perlu kata sandi lagi.",hint:"Sama pentingnya, atau tidak berhubungan?"},
{n:46,type:"mcq",micro:"Membuat kata sandi untuk akun bank/uang",q:"Untuk akun yang berhubungan dengan uang, langkah ekstra yang disarankan:",options:["Pakai kata sandi yang sama dengan email biasa supaya mudah diingat, dan matikan 2FA karena merepotkan saat login","Tidak perlu penjagaan ekstra, karena akun yang berhubungan dengan uang sudah dilindungi bank dari peretasan","Kata sandi paling kuat & unik, 2FA wajib dinyalakan, & waspada ekstra terhadap pesan/email yang meminta info akun"],answer:2,explain:"Akun finansial adalah target favorit penipu. Lapisan keamanan & kewaspadaan harus paling tinggi di sana.",hint:"Paling kuat + 2FA + waspada ekstra, atau sama seperti akun biasa?"},
{n:47,type:"mcq",micro:"Menguji kekuatan kata sandi",q:"Alat pemeriksa kekuatan kata sandi (yang tepercaya & tidak meminta sandi aslimu dikirim) bisa membantu...",options:["Memberi gambaran kasar seberapa cepat sandi bisa ditebak, sebagai panduan memperkuatnya","Menjamin bahwa sandimu tidak akan dibobol, sehingga kamu tidak perlu berhati-hati lagi soal hal lain","Menggantikan kebutuhan berpikir sendiri soal keamanan, karena hasil alatnya benar untuk setiap keadaan"],answer:0,explain:"Alat ini panduan, bukan jaminan mutlak. Tetap gabungkan dengan prinsip dasar: panjang, acak, unik, & tidak berhubungan info pribadi.",hint:"Memberi gambaran & panduan, atau jaminan mutlak?"},
{n:48,type:"mcq",micro:"Kata sandi untuk akun anak/game",q:"Akun game yang berisi item/progres yang kamu hargai tetap layak dijaga karena...",options:["Game punya keamanan otomatis yang sulit ditembus, jadi akun game tidak butuh kata sandi yang kuat","Sudah ada 'nilai' (waktu, usaha, kadang uang) di dalamnya, & bisa jadi celah ke info lain (email terhubung)","Akun game tidak berharga, karena isinya hanya hiburan dan tidak berhubungan dengan data atau email terhubung"],answer:1,explain:"Banyak orang meremehkan keamanan akun game, padahal sering berisi hal berharga & terhubung ke email yang lebih penting.",hint:"Ada nilai & terhubung ke email, atau tidak pernah berharga?"},
{n:49,type:"mcq",micro:"Menghadapi 'lupa kata sandi'",q:"Saat lupa kata sandi, cara aman memulihkannya:",options:["Minta orang lain menebak kata sandimu untukmu, misalnya teman yang kebetulan pernah melihatmu mengetiknya sebelumnya di kelas","Buat akun baru setiap kali lupa kata sandi, lalu tinggalkan akun lama begitu saja beserta seluruh data dan teman-teman di dalamnya","Pakai fitur 'lupa kata sandi' resmi lewat email/nomor terdaftar, jangan klik tautan pemulihan dari pesan yang tidak kamu minta sendiri"],answer:2,explain:"Selalu mulai dari halaman resmi layanan, bukan dari tautan di pesan/email yang tiba-tiba datang mengaku 'reset password'.",hint:"Mulai dari halaman resmi, jangan klik tautan tak diminta, atau buat akun baru?"},
{n:50,type:"order",micro:"Menyalakan 2FA",q:"Urutkan langkah umum menyalakan verifikasi dua langkah pada sebuah akun.",items:["Masuk ke pengaturan keamanan akun","Pilih metode 2FA (aplikasi autentikasi biasanya lebih aman dari SMS)","Simpan kode cadangan (backup codes) di tempat aman, bukan di HP yang sama","Uji dengan logout & login ulang untuk memastikan berfungsi"],answer:[0,1,2,3],explain:"Masuk pengaturan → pilih metode → simpan kode cadangan terpisah → uji. Kode cadangan penting kalau HP-mu hilang/rusak.",hint:"Menyimpan kode cadangan sebelum atau sesudah menguji login ulang?"},
{n:51,type:"mcq",micro:"Kode cadangan 2FA",q:"'Kode cadangan' (backup codes) untuk 2FA berguna karena...",options:["Bisa dipakai masuk kalau HP tempat aplikasi autentikasimu hilang atau rusak","Menggantikan kata sandi, sehingga kamu tak perlu lagi menjaga sandi akunmu","Harus dipakai setiap login seperti sandi biasa, bahkan saat HP dan aplikasi autentikasi masih normal"],answer:0,explain:"Kode cadangan adalah jalan darurat. Simpan di tempat lain yang aman (bukan di HP yang sama), agar tetap bisa dipakai bila HP-mu bermasalah.",hint:"Jalan darurat saat HP bermasalah, atau menggantikan sandi selamanya?"},
{n:52,type:"tf",micro:"Mengetik kata sandi di HP orang lain",q:"Benar atau Salah: Login ke akun pentingmu di HP milik orang lain boleh dilakukan kapan saja tanpa perlu logout setelahnya.",answer:false,explain:"Sebaliknya, kamu tidak tahu apakah HP itu bersih dari program pencatat ketikan atau aplikasi jahat. Sebaiknya dihindari kecuali benar-benar darurat, & segera logout setelahnya.",hint:"Hindari kecuali darurat & logout, atau bebas dilakukan kapan saja?"},
{n:53,type:"mcq",micro:"Kata sandi & aplikasi tak resmi",q:"Aplikasi tidak resmi yang menjanjikan 'cek kekuatan sandimu, masukkan sandi aslimu di sini' patut dicurigai karena...",options:["Tidak ada risikonya","Bisa jadi cara mengumpulkan kata sandi asli orang untuk disalahgunakan","Semua aplikasi seperti itu pasti aman"],answer:1,explain:"Jangan pernah memasukkan kata sandi ASLI ke alat pihak ketiga yang tidak tepercaya, meski dalih 'mengecek keamanan'.",hint:"Bisa mengumpulkan sandi asli, atau pasti aman?"},
{n:54,type:"mcq",micro:"Perubahan kata sandi setelah berbagi perangkat",q:"Kamu terpaksa login akun pentingmu di komputer warnet karena darurat. Setelah itu, langkah bijak:",options:["Tidak perlu melakukan apa-apa lagi, karena warnet otomatis menghapus semua jejak login setelah dipakai","Biarkan akun tetap login supaya lain kali langsung terbuka tanpa mengetik sandi, apalagi saat terburu-buru","Logout, & begitu ada kesempatan di perangkat sendiri yang aman, ganti kata sandinya sebagai tindakan pencegahan"],answer:2,explain:"Komputer publik berisiko punya perangkat lunak pencatat. Mengganti sandi setelahnya adalah langkah pencegahan yang wajar.",hint:"Logout lalu ganti sandi nanti, atau biarkan / tak perlu apa-apa?"},
{n:55,type:"mcq",micro:"Kata sandi & pembaruan aplikasi pengelola",q:"Kalau kamu memakai pengelola kata sandi, kebiasaan yang baik:",options:["Lindungi juga akun pengelola itu dengan kata sandi utama yang sangat kuat & 2FA, karena ia menyimpan 'kunci ke semua kunci'","Kata sandi utamanya boleh lemah dan mudah, karena hanya kamu yang tahu bahwa kamu memakai pengelola kata sandi dan isinya tersimpan rapi","Tidak perlu mengamankannya khusus, sebab pengelola kata sandi sudah dilindungi sistem sepenuhnya dan tidak mungkin bocor, diretas, atau dibobol"],answer:0,explain:"Pengelola kata sandi menyatukan semua sandimu di satu tempat. Kata sandi utamanya harus paling kuat dari semuanya.",hint:"Lindungi ekstra kuat, atau boleh lemah / tak perlu khusus?"},
{n:56,type:"tf",micro:"Semakin banyak syarat semakin aman?",q:"Benar atau Salah: Sebuah situs yang mewajibkan kata sandi sangat rumit tapi TIDAK menawarkan 2FA pasti lebih aman daripada situs dengan syarat sandi sedang tapi menawarkan 2FA.",answer:false,explain:"Sebaliknya, belum tentu, 2FA menambah lapisan pertahanan yang berbeda. Kombinasi 'sandi cukup kuat + 2FA' sering lebih efektif daripada 'sandi sangat rumit tanpa lapisan tambahan'.",hint:"Belum tentu lebih aman tanpa 2FA, atau sandi rumit selalu menang?"},
{n:57,type:"mcq",micro:"Menjaga privasi jawaban keamanan",q:"Kalau pertanyaan keamanan situs tidak bisa diubah (mis. wajib 'kota kelahiran'), cara tetap menjaganya:",options:["Tidak masalah membagikannya di mana saja, karena kota kelahiran atau sekolah hanyalah informasi biasa yang tidak berkaitan dengan keamanan akun","Berikan jawaban yang benar bila memang wajib, tapi jangan memposting info itu secara terbuka di media sosial (kota kelahiran, sekolah, dll)","Selalu berbohong pada semua formulir resmi, termasuk formulir sekolah dan bank, karena jawaban jujur tidak pernah aman untuk dituliskan"],answer:1,explain:"Kalau situs mewajibkan data sebenarnya, jaga agar info itu tidak tersebar luas di tempat lain (profil publik) supaya tidak mudah dicocokkan.",hint:"Jaga info itu tidak tersebar di tempat lain, atau bebas dibagikan?"},
{n:58,type:"mcq",micro:"Kata sandi anak kelas atas",q:"Ketika mulai memakai banyak akun (email, media sosial, sekolah, game), kebiasaan yang membantu jangka panjang:",options:["Tunggu sampai sudah punya banyak akun yang tak terhitung baru mulai memikirkan sistem pengelolaan, karena sebelum itu belum ada yang perlu diatur","Tidak perlu sistem apa pun karena semua akun sama pentingnya dan ingatan manusia pasti cukup untuk mengingat puluhan kata sandi berbeda","Buat sistem pribadi (mis. mengelompokkan tingkat kepentingan akun) & pakai pengelola kata sandi sejak dini, sebelum jumlah akun terlalu banyak untuk diingat"],answer:2,explain:"Membangun kebiasaan baik sejak jumlah akun masih sedikit lebih mudah daripada memperbaiki kekacauan setelah puluhan akun menumpuk.",hint:"Bangun sistem sejak dini, atau tunggu / tanpa sistem?"},
{n:59,type:"mcq",micro:"Kata sandi & jejak digital",q:"Info yang kamu bagikan di media sosial (nama hewan peliharaan, sekolah, nama ibu) bisa berbahaya untuk keamanan akun karena...",options:["Sering dipakai sebagai kata sandi atau jawaban pertanyaan keamanan, sehingga membocorkannya membantu penebak","Tidak terkait dengan keamanan akun, karena penebak memakai alat otomatis dan tidak mencari info pribadi pemilik","Hanya berbahaya bagi orang dewasa yang punya rekening, sedangkan akun anak dan remaja tidak menarik bagi peretas"],answer:0,explain:"Info yang terasa 'biasa saja' untuk dibagikan sering justru bahan baku kata sandi & pertanyaan keamanan orang.",hint:"Sering dipakai sebagai bahan sandi/jawaban keamanan, atau tak berhubungan?"},
{n:60,type:"open",micro:"Audit kata sandi",q:"Lakukan 'audit' kata sandi sederhana (tanpa menuliskan sandi aslimu). Untuk 5 akunmu, tulis dalam tabel sederhana: nama akun, apakah uniknya (Ya/Tidak), apakah 2FA aktif (Ya/Tidak/Tidak tersedia), tingkat kepentingan (Tinggi/Sedang/Rendah). Lalu simpulkan: (a) akun mana yang paling berisiko & kenapa, (b) 2 tindakan konkret yang akan kamu lakukan minggu ini, urut berdasarkan prioritas.",explain:"Jawaban baik: tabel dengan 5 akun & tiga kolom yang diisi jujur, identifikasi akun paling berisiko dengan alasan yang menggabungkan kepentingan + keunikan + 2FA (bukan hanya satu faktor), & dua tindakan konkret yang diurutkan berdasarkan prioritas risiko, bukan sekadar 'akan lebih hati-hati'.",hint:"Akun paling berisiko biasanya yang menggabungkan: penting + sandi dipakai ulang + belum ada 2FA.",sample:"Tabel: 1. Email utama, Unik: Ya, 2FA: Ya, Kepentingan: Tinggi. 2. Media sosial A, Unik: Tidak (sama dengan game lama), 2FA: Tidak, Kepentingan: Tinggi. 3. Akun sekolah, Unik: Ya, 2FA: Tidak tersedia, Kepentingan: Tinggi. 4. Forum hobi, Unik: Tidak (sama dengan media sosial A), 2FA: Tidak tersedia, Kepentingan: Rendah. 5. Game daring, Unik: Tidak (sandi yang sama dipakai di #2 & #4), Kepentingan: Sedang. (a) Akun paling berisiko: media sosial A, karena kepentingannya tinggi (banyak info pribadi & kontak), sandinya tidak unik (dipakai juga di forum hobi & game), & belum ada 2FA, jadi kalau salah satu dari tiga akun ini bocor, ketiganya ikut terancam sekaligus. (b) Tindakan minggu ini, urut prioritas: (1) Ganti kata sandi media sosial A jadi sandi baru yang unik & nyalakan 2FA di akun itu, karena ini kepentingan tertinggi dengan risiko terbesar. (2) Ganti kata sandi forum hobi & game daring masing-masing jadi sandi unik yang berbeda (tidak perlu sekuat akun tinggi, tapi tidak boleh sama lagi satu sama lain), untuk memutus rantai 'satu bocor semua ikut'."},
{n:61,type:"mcq",micro:"Phishing terkait kata sandi",q:"Email 'Akunmu akan dihapus! Klik di sini & masukkan kata sandi untuk konfirmasi' kemungkinan besar adalah...",options:["Email biasa dari layanan itu sendiri, jadi cukup klik tautannya dan ketik kata sandi agar akun tidak dihapus","Percobaan phishing (pancingan) untuk mencuri kata sandimu lewat rasa panik & terburu-buru","Peringatan resmi yang harus dituruti dalam hitungan menit, jadi langsung ikuti petunjuknya tanpa memeriksa"],answer:1,explain:"Layanan resmi jarang meminta kata sandi lewat tautan email & sering memakai tekanan waktu untuk membuatmu tidak berpikir jernih.",hint:"Percobaan phishing, atau peringatan resmi yang harus dituruti?"},
{n:62,type:"mcq",micro:"Membedakan tautan resmi & palsu",q:"Cara memeriksa apakah tautan 'reset password' yang kamu terima asli:",options:["Klik saja tautannya dan lihat apa yang terjadi, karena kalau ternyata palsu kamu masih bisa langsung menutup halamannya tanpa risiko","Percaya saja kalau tampilan halamannya sangat mirip aslinya, termasuk logo, warna, dan huruf, karena penipu tidak mungkin bisa meniru sedetail itu","Jangan klik tautan di pesan; buka situs resminya sendiri lewat mengetik alamat atau bookmark, lalu cari opsi lupa kata sandi di sana"],answer:2,explain:"Tampilan bisa dipalsukan dengan mudah. Cara paling aman: jangan ikuti tautan dari pesan, datangi situs resmi secara mandiri.",hint:"Datangi situs resmi sendiri, atau klik & percaya tampilan?"},
{n:63,type:"mcq",micro:"Tekanan sosial berbagi sandi",q:"Pacar/teman dekat minta kata sandimu 'sebagai bukti kepercayaan'. Sikap yang sehat:",options:["Kepercayaan tidak diukur dari berbagi kata sandi; kamu boleh menolak dengan tetap menjaga hubungan baik","Berikan saja agar hubungan tidak renggang, karena menolak berarti kamu tidak percaya dan merusak persahabatan","Berikan sebagian karakter saja, misalnya setengahnya, supaya terlihat percaya tetapi tetap aman"],answer:0,explain:"Permintaan seperti ini sering jadi awal kontrol yang tidak sehat. Batas pribadi tetap berhak dijaga dalam hubungan apa pun.",hint:"Menolak dengan sehat, atau berikan demi hubungan?"},
{n:64,type:"tf",micro:"Berbagi sandi = berbagi seluruh identitas digital",q:"Benar atau Salah: Memberi tahu kata sandi akun kepada orang lain sama dengan memberi mereka akses penuh ke pesan, foto, & identitasmu di akun itu.",answer:true,explain:"Siapa pun yang tahu kata sandimu bisa berpura-pura jadi kamu di akun itu, membaca semua isi pribadinya.",hint:"Sama dengan akses penuh, atau hanya akses terbatas?"},
{n:65,type:"mcq",micro:"Kata sandi setelah putus hubungan/berselisih",q:"Kalau kamu pernah berbagi kata sandi dengan seseorang yang sekarang tidak lagi dekat (mantan teman/pacar), langkah bijak:",options:["Percaya saja bahwa mereka tidak akan memakainya, karena orang yang pernah dekat bisa dipercaya dan tidak berubah","Ganti kata sandi akun itu sesegera mungkin, siapa pun tetap bisa memakainya selama tahu sandinya","Biarkan saja karena sudah lama, sebab kata sandi yang lama tidak dipakai akan kedaluwarsa dengan sendirinya"],answer:1,explain:"Hubungan bisa berubah, tapi akses digital yang diberikan tidak otomatis dicabut. Kamu harus aktif menggantinya.",hint:"Ganti segera, atau biarkan / percaya begitu saja?"},
{n:66,type:"mcq",micro:"Menyeimbangkan kenyamanan & keamanan",q:"Mematikan semua verifikasi tambahan karena 'ribet' adalah pertukaran yang perlu dipikirkan karena...",options:["Kenyamanan lebih penting daripada keamanan, jadi risiko kebocoran akun tidak perlu dipikirkan dalam keadaan apa pun","Tidak ada pertukaran, keduanya bisa maksimal bersamaan, sehingga mematikan verifikasi tidak mengubah keamanan","Kenyamanan bertambah sedikit, tapi risiko kebocoran akun bertambah jauh lebih besar untuk akun penting"],answer:2,explain:"Setiap lapisan keamanan menambah sedikit langkah tapi mengurangi risiko besar. Untuk akun penting, pertukaran itu biasanya sepadan.",hint:"Kenyamanan kecil vs risiko besar, atau kenyamanan selalu menang?"},
{n:67,type:"mcq",micro:"Menilai layanan sebelum mendaftar",q:"Sebelum membuat akun di layanan baru yang meminta banyak data pribadi & kata sandi, pertimbangan yang bijak:",options:["Apakah aku benar-benar butuh layanan ini? Apakah tampak tepercaya (reputasi, kebijakan privasi)? Data apa yang sebenarnya wajib diisi?","Daftar saja di layanan yang kelihatan menarik tanpa berpikir panjang, karena mencoba layanan baru menyenangkan dan kecil risikonya","Isi semua kolom meski opsional, termasuk nomor telepon dan alamat lengkap, karena makin banyak data makin cepat disetujui"],answer:0,explain:"Setiap akun baru adalah titik risiko tambahan. Menimbang kebutuhan & kepercayaan sebelum mendaftar mengurangi jejak yang harus dijaga.",hint:"Timbang kebutuhan & kepercayaan, atau daftar semua / isi semua kolom?"},
{n:68,type:"tf",micro:"Kata sandi kuat tidak menjamin 100% aman",q:"Benar atau Salah: Kata sandi yang kuat & 2FA aktif sangat mengurangi risiko, tapi tidak menjamin akun 100% tidak akan pernah dibobol (mis. bila layanan itu sendiri diretas).",answer:true,explain:"Keamanan mengurangi risiko, bukan menghapusnya sepenuhnya. Layanan yang kamu pakai juga bisa jadi korban serangan besar di luar kendalimu.",hint:"Mengurangi risiko tapi tak menjamin 100%, atau menjamin sepenuhnya aman?"},
{n:69,type:"mcq",micro:"Menanggapi teman yang kata sandinya lemah",q:"Kamu tahu temanmu memakai kata sandi yang sangat lemah untuk akun pentingnya. Sikap yang baik:",options:["Beritahu di depan teman-teman lain agar ia sadar dan malu lalu berubah","Beri tahu dengan baik & jelaskan risikonya, tanpa menghakimi atau mempermalukannya","Diam saja karena itu bukan urusanmu, meski kamu tahu risikonya bisa merugikan temanmu"],answer:1,explain:"Berbagi pengetahuan keamanan dengan cara yang menghormati membantu orang lain tanpa membuat mereka defensif atau malu.",hint:"Beri tahu dengan baik secara pribadi, atau diam / permalukan?"},
{n:70,type:"tf",micro:"Keamanan akun itu proses berkelanjutan",q:"Benar atau Salah: Setelah mengamankan sebuah akun sekali (sandi kuat, 2FA), kamu tidak perlu lagi memikirkan atau memeriksa keamanannya seumur hidup akun itu.",answer:false,explain:"Sebaliknya, ancaman berubah & berkembang. Menjaga akun tetap aman adalah kebiasaan berkelanjutan (memperbarui, memeriksa, waspada), bukan tindakan sekali selesai.",hint:"Kebiasaan berkelanjutan, atau tindakan sekali selesai?"},
{n:71,type:"mcq",micro:"Menilai permintaan info akun",q:"Bentuk pertanyaan yang HARUS membuatmu curiga:",options:["'Cek pengaturan keamanan akunmu di halaman resmi'","'Nyalakan verifikasi dua langkah untuk keamanan tambahan'","'Kirim kata sandimu ke sini agar tim kami bisa memeriksa akunmu'"],answer:2,explain:"Tidak ada tim dukungan resmi yang sah yang perlu tahu kata sandimu untuk 'memeriksa'. Ini pola klasik penipuan.",hint:"Meminta kata sandi dikirim, atau menyarankan langkah aman?"},
{n:72,type:"mcq",micro:"Kata sandi & privasi keluarga",q:"Bila orang tua meminta tahu kata sandi akunmu untuk pengawasan, cara sehat menyikapinya:",options:["Bicarakan dengan terbuka tentang alasan & batasnya, karena keluarga bisa punya alasan sah, tapi tetap wajar mendiskusikan bagaimana privasi & kepercayaan dijaga bersama","Menolak dengan keras tanpa mau berdiskusi, karena privasi anak harus dijaga mutlak dan orang tua tidak punya alasan yang sah untuk meminta sandi akun anaknya","Memberikannya begitu saja tanpa membicarakan alasan atau batasnya, karena orang tua berhak tahu semua urusan anaknya"],answer:0,explain:"Ini situasi yang butuh komunikasi, bukan aturan mutlak satu arah. Keluarga punya dinamika kepercayaan & keamanan yang berbeda dari hubungan dengan orang asing.",hint:"Diskusikan terbuka, atau menolak keras / memberi tanpa bicara?"},
{n:73,type:"mcq",micro:"Membaca kebijakan sebelum setuju",q:"Sebelum menekan 'Setuju' pada syarat & ketentuan sebuah layanan baru yang meminta banyak data, kebiasaan yang lebih bijak:",options:["Menghindari pendaftaran akun di layanan baru, karena syarat dan ketentuan berisi jebakan dan layanan baru jarang berguna","Setidaknya baca ringkasan atau bagian penting tentang data apa yang dikumpulkan & untuk apa, jangan hanya klik cepat","Klik setuju secepatnya agar langsung bisa dipakai, karena syarat dan ketentuan hanya formalitas yang isinya sama di semua layanan"],answer:1,explain:"Kebiasaan mengklik cepat tanpa membaca membuat kita tidak sadar data apa yang sebenarnya kita berikan.",hint:"Baca bagian penting, atau klik cepat / hindari semua akun?"},
{n:74,type:"mcq",micro:"Kata sandi & pemulihan yang gagal",q:"Kalau semua jalur pemulihan akun (email & nomor lama) sudah tidak aktif & kamu benar-benar terkunci, pelajarannya:",options:["Tidak ada pelajaran yang bisa diambil, karena terkunci dari akun hanyalah nasib buruk dan tidak terkait kebiasaanmu","Sebaiknya jangan memakai email atau nomor pemulihan, karena jalur pemulihan membuka celah baru bagi peretas","Pentingnya selalu memperbarui info pemulihan begitu email/nomor berganti, agar situasi ini tidak terulang"],answer:2,explain:"Info pemulihan yang basi adalah penyebab umum kehilangan akun permanen. Memperbaruinya saat berganti adalah kebiasaan pencegahan.",hint:"Perbarui info pemulihan saat berganti, atau anggap nasib buruk / hindari fitur itu?"},
{n:75,type:"order",micro:"Menanggapi email phishing yang mencurigakan",q:"Urutkan langkah menanggapi email yang minta kamu 'login segera & masukkan kata sandi' lewat sebuah tautan.",items:["Jangan klik tautannya; perhatikan tanda-tanda mencurigakan (alamat pengirim aneh, mendesak, salah eja)","Buka situs resminya sendiri secara terpisah (ketik alamat/bookmark) untuk cek apakah memang ada masalah akun","Kalau tidak ada masalah nyata di situs resmi, abaikan atau laporkan email itu sebagai phishing","Kalau pernah terlanjur mengklik & memasukkan sandi, segera ganti kata sandi itu dari jalur resmi"],answer:[0,1,2,3],explain:"Jangan klik dulu → verifikasi mandiri lewat jalur resmi → abaikan/laporkan bila palsu → bila terlanjur, segera ganti sandi. Verifikasi mandiri adalah kunci.",hint:"Memverifikasi lewat situs resmi sebelum atau sesudah mengklik tautan di email?"},
{n:76,type:"tf",micro:"Kata sandi bukan satu-satunya pertahanan",q:"Benar atau Salah: Kata sandi yang kuat adalah bagian penting keamanan digital, tapi perlu ditemani kebiasaan lain (2FA, waspada phishing, update perangkat) untuk perlindungan yang benar-benar baik.",answer:true,explain:"Keamanan digital adalah gabungan banyak lapisan. Kata sandi kuat saja tidak cukup melawan phishing atau perangkat yang tidak diperbarui.",hint:"Perlu ditemani kebiasaan lain, atau kata sandi kuat saja cukup?"},
{n:77,type:"mcq",micro:"Kata sandi & konsekuensi jangka panjang",q:"Kebiasaan keamanan akun yang dibangun sejak muda bermanfaat jangka panjang karena...",options:["Makin dewasa, makin banyak akun penting (pekerjaan, keuangan, identitas resmi) yang bergantung pada kebiasaan yang sama","Kebiasaan ini hanya relevan untuk anak sekolah, sebab setelah dewasa akun penting dilindungi sistem tanpa perlu diurus sendiri","Akun penting baru muncul setelah dewasa, jadi belum perlu dipikirkan sekarang dan kebiasaannya bisa dipelajari mendadak nanti"],answer:0,explain:"Kebiasaan yang dilatih sekarang (sandi kuat & unik, 2FA, waspada phishing) akan terus dipakai & makin krusial di masa depan.",hint:"Bermanfaat untuk akun penting di masa depan, atau hanya relevan sekarang?"},
{n:78,type:"mcq",micro:"Menyeimbangkan ingatan & keamanan",q:"Kalau kamu benar-benar sulit mengingat sandi yang sangat acak untuk SEMUA akun, kompromi yang wajar:",options:["Tulis semua sandi di grup chat pribadi supaya mudah dicari lagi kapan saja, karena grup berisi orang-orang yang kamu percayai sepenuhnya","Pakai pengelola kata sandi untuk sebagian besar akun, & hafalkan hanya sedikit sandi terpenting (akun utama & pengelola sandi itu sendiri) dengan sangat kuat","Buat semua sandi sangat pendek dan sama polanya agar mudah diingat tanpa alat bantu, walau mudah ditebak oleh orang lain atau mesin"],answer:1,explain:"Strategi realistis: andalkan alat untuk yang banyak, & investasikan usaha mengingat hanya pada beberapa 'kunci utama' yang paling penting.",hint:"Andalkan pengelola sandi + hafal sedikit kunci utama, atau perpendek semua / catat di chat?"},
{n:79,type:"mcq",micro:"Keamanan sebagai kebiasaan, bukan ketakutan",q:"Cara sehat memandang kebiasaan keamanan kata sandi:",options:["Sesuatu yang membuatmu cemas dan curiga pada setiap orang, sehingga sebaiknya kamu menjauh dari dunia digital","Hal yang tidak perlu dipikirkan, karena dunia digital aman dan orang yang berniat jahat sangat jarang ditemui","Seperti mengunci pintu rumah, hal wajar & rutin yang melindungi, bukan tanda bahwa dunia digital selalu menakutkan"],answer:2,explain:"Kebiasaan aman yang dilakukan tanpa panik, seperti rutinitas biasa, lebih berkelanjutan daripada ketakutan yang melelahkan.",hint:"Rutinitas wajar seperti mengunci pintu, atau sumber cemas terus-menerus / diabaikan?"},
{n:80,type:"open",micro:"Menanggapi skenario penipuan kata sandi",q:"Bayangkan kamu menerima pesan: 'Selamat! Akunmu terpilih dapat hadiah, login sekarang di [tautan] dalam 10 menit sebelum hangus!' Analisis: (a) minimal 3 tanda kecurigaan dalam pesan ini, (b) apa yang SEHARUSNYA kamu lakukan langkah demi langkah, (c) kenapa 'waktu terbatas' & 'hadiah' sering dipakai penipu, (d) bagaimana kamu akan menjelaskan bahaya ini ke adik/teman yang lebih muda dengan bahasa sederhana.",explain:"Jawaban baik: minimal 3 tanda kecurigaan yang spesifik & benar (urgensi, hadiah tak diminta, tautan bukan sumber resmi, dll), langkah yang benar (jangan klik, verifikasi mandiri, laporkan), penjelasan psikologis yang masuk akal tentang kenapa taktik itu efektif, & penjelasan untuk adik yang sederhana, konkret, & mudah diingat (bukan penjelasan teknis rumit).",hint:"Bagian (d) harus benar-benar disederhanakan, bayangkan menjelaskan ke anak yang lebih muda, pakai aturan pendek yang mudah diingat.",sample:"(a) Tanda kecurigaan: (1) Mendesak dengan batas waktu sangat singkat (10 menit) untuk membuatku panik & tidak sempat berpikir jernih. (2) Menjanjikan hadiah yang tidak kuminta atau kuikuti undiannya. (3) Meminta login lewat tautan di pesan, bukan lewat aplikasi/situs resmi yang biasa kupakai. (4) Kemungkinan alamat pengirim atau tautannya terlihat aneh/tidak resmi kalau diperiksa. (b) Yang seharusnya dilakukan: jangan klik tautannya sama sekali; kalau penasaran apakah ini asli, buka aplikasi/situs resminya sendiri (bukan lewat tautan itu) & cek apakah memang ada info hadiah semacam itu di sana; kalau tidak ada, abaikan atau laporkan/blokir pengirimnya; jangan pernah memasukkan kata sandi lewat tautan dari pesan yang tidak diminta. (c) Kenapa 'waktu terbatas' & 'hadiah' efektif: keduanya memicu emosi (takut kehilangan kesempatan, senang dapat hadiah) yang membuat orang bertindak cepat tanpa berpikir kritis, ini teknik manipulasi psikologis klasik yang dipakai penipu karena berhasil pada banyak orang. (d) Penjelasan sederhana untuk adik: 'Kalau ada pesan yang bilang kamu menang hadiah tapi harus buru-buru login pakai kata sandimu lewat sebuah link, itu HAMPIR SELALU tipuan. Orang jahat sengaja bikin kamu buru-buru & senang supaya kamu lupa berpikir. Aturannya gampang: kalau diminta buru-buru masukin kata sandi lewat link, JANGAN, cerita dulu ke kakak/orang tua.'"},
{n:81,type:"mcq",micro:"Skenario: teman minta login-kan akun",q:"Temanmu HP-nya rusak & minta kamu login ke akunnya di HP-mu untuk mengecek sesuatu. Sikap yang bijak:",options:["Bantu bila memang mendesak, tapi setelah selesai pastikan logout sepenuhnya & sarankan dia ganti kata sandi begitu HP-nya kembali normal","Menolak tegas dan tidak pernah membantu dalam keadaan apa pun, sekalipun temanmu sedang butuh sekali dan kamu bisa mengawasinya langsung di sampingmu","Simpan sandinya di HP-mu untuk jaga-jaga, supaya lain kali kamu bisa membukakan akunnya kapan saja tanpa perlu menghubunginya lagi"],answer:0,explain:"Membantu dalam kondisi darurat wajar, tapi tetap jaga kebersihan digital: logout total & sarankan langkah pencegahan setelahnya.",hint:"Bantu tapi logout total & sarankan ganti sandi, atau tolak total / simpan sandinya?"},
{n:82,type:"mcq",micro:"Skenario: pesan dari 'teman' yang aneh",q:"Akun media sosial temanmu tiba-tiba mengirimimu pesan aneh minta transfer uang mendesak. Kemungkinan besar & sikap tepat:",options:["Balas pesan di akun yang sama dan minta bukti, lalu percayai jawabannya, karena peretas pasti tidak bisa menjawab dengan meyakinkan seperti temanmu","Akun temanmu kemungkinan diretas; hubungi dia lewat cara lain (telepon langsung) untuk memastikan sebelum melakukan apa pun","Langsung transfer uang yang diminta karena itu temanmu dan keadaannya mendesak, sebab menunda berarti kamu tidak mau menolong temanmu sendiri"],answer:1,explain:"Akun yang diretas sering dipakai menipu kontak pemiliknya. Verifikasi lewat jalur komunikasi lain (bukan akun yang sama) adalah langkah aman.",hint:"Verifikasi lewat jalur lain, atau langsung transfer / balas di akun sama?"},
{n:83,type:"mcq",micro:"Skenario: kata sandi lama masih dipakai",q:"Kamu sadar sebuah kata sandi lama (dibuat 3 tahun lalu, pendek & sederhana) masih dipakai di beberapa akun. Langkah:",options:["Biarkan saja karena belum pernah ada masalah selama tiga tahun ini, dan kata sandi lama yang pendek pasti sudah terbukti aman dipakai","Ganti semuanya jadi satu kata sandi baru yang sama untuk semua akun, supaya mudah diingat dan tidak perlu mengurus satu per satu","Buat daftar akun yang memakainya, ganti satu per satu dengan sandi unik & kuat, prioritaskan yang paling penting dulu"],answer:2,explain:"'Belum pernah bermasalah' bukan jaminan aman. Memperbaikinya secara bertahap dengan prioritas yang jelas adalah langkah realistis.",hint:"Ganti bertahap dengan prioritas, atau biarkan / ganti jadi satu sandi baru yang sama?"},
{n:84,type:"mcq",micro:"Skenario: aplikasi sekolah tidak mendukung 2FA",q:"Sistem belajar daring sekolahmu tidak menyediakan opsi 2FA. Cara tetap menjaga keamanannya:",options:["Pastikan kata sandinya sangat kuat & unik, jaga perangkat tetap terkunci, & laporkan ke pihak sekolah bila ada kekhawatiran soal keamanan sistem","Anggap saja tidak perlu dijaga ketat karena tidak ada opsi 2FA, sehingga kata sandi sederhana pun sudah cukup untuk sistem sekolah","Pakai kata sandi yang sama dengan akun lain karena 'toh tidak ada 2FA juga', jadi tidak ada gunanya repot membuat yang berbeda"],answer:0,explain:"Kalau satu lapisan tidak tersedia, perkuat lapisan lain yang bisa kamu kendalikan (kekuatan sandi, keunikan, kunci perangkat).",hint:"Perkuat lapisan lain yang bisa dikendalikan, atau anggap tak perlu dijaga?"},
{n:85,type:"tf",micro:"Kebiasaan kecil, dampak besar",q:"Benar atau Salah: Kebiasaan sederhana seperti memakai kata sandi unik & menyalakan 2FA bisa mencegah sebagian besar jenis pembobolan akun yang paling umum terjadi.",answer:true,explain:"Sebagian besar insiden pembobolan akun berasal dari sandi lemah/dipakai ulang & tidak adanya lapisan kedua, bukan dari serangan yang sangat canggih.",hint:"Mencegah sebagian besar kasus umum, atau tidak banyak berpengaruh?"},
{n:86,type:"mcq",micro:"Skenario: adik ingin akun pertamanya",q:"Adikmu yang masih kecil ingin membuat akun pertamanya. Kamu diminta membantu. Yang kamu ajarkan:",options:["Biarkan dia memakai nama dan tanggal lahirnya sendiri sebagai sandi supaya gampang diingat, karena anak kecil tidak mungkin jadi sasaran peretas","Cara membuat kata sandi yang kuat tapi sederhana untuk dia ingat, & aturan dasar 'jangan pernah beri tahu kata sandi ke siapa pun kecuali orang tua'","Buatkan kata sandinya sendiri tanpa melibatkannya sama sekali dan jangan beri tahu dia, supaya ia tidak perlu belajar apa pun tentang keamanan"],answer:1,explain:"Melibatkan & mengajarkan sejak dini (dengan bahasa sederhana) membangun kebiasaan baik yang akan terus terbawa.",hint:"Ajarkan & libatkan dengan aturan sederhana, atau buatkan sendiri / pakai info pribadi?"},
{n:87,type:"mcq",micro:"Skenario: akun dipakai untuk hal yang bukan kamu",q:"Kamu melihat unggahan dari akunmu sendiri yang tidak pernah kamu buat. Urutan sikap yang tepat:",options:["Hapus saja unggahannya lalu lupakan, tanpa mengganti kata sandi, karena yang penting unggahan aneh itu sudah hilang dari akunmu sekarang","Biarkan saja karena itu mungkin hanya bug sesaat dari aplikasi, dan kamu tidak perlu memberi tahu siapa pun atau mengubah apa pun","Ganti kata sandi segera, cek sesi login lain, hapus unggahan itu, & beri tahu kontak dekat bahwa akunmu sempat diretas"],answer:2,explain:"Tanda peretasan nyata butuh respons cepat & menyeluruh: kunci ulang akun, bersihkan sesi asing, & informasikan agar orang lain tidak tertipu.",hint:"Ganti sandi + cek sesi + hapus + beri tahu, atau abaikan / hapus saja?"},
{n:88,type:"mcq",micro:"Skenario: memilih antara dua kata sandi",q:"Kamu harus memilih antara 'B3rangkatSek0lah!' (mudah diingat, ada di kalimat umum) & 'j4Rn5#kL9wQ2p' (acak murni, sulit diingat). Untuk akun sangat penting, pertimbangan terbaik:",options:["Pakai yang acak murni & simpan di pengelola kata sandi, karena tidak perlu mengandalkan ingatan untuk akun paling penting","Selalu pilih yang mudah diingat apa pun jenis akunnya, karena sandi yang bisa diingat selalu lebih baik daripada yang sulit diingat manusia","Gabungkan keduanya menjadi satu kalimat sangat panjang dan pakai untuk semua akunmu tanpa berpikir lebih jauh soal penyimpanan atau keunikannya"],answer:0,explain:"Untuk akun berisiko tinggi, keacakan murni + alat penyimpan aman mengalahkan kemudahan mengingat semata.",hint:"Acak murni + pengelola sandi untuk akun penting, atau selalu pilih yang mudah diingat?"},
{n:89,type:"mcq",micro:"Skenario: menjelaskan ke orang tua yang skeptis",q:"Orang tuamu menganggap pengelola kata sandi 'berbahaya karena semua sandi ada di satu tempat'. Cara menanggapi dengan hormat & informatif:",options:["Setuju dengan orang tuamu dan berhenti memakai alat keamanan tambahan, lalu tetap memakai sandi sederhana yang sama di banyak akun seperti sebelumnya, karena itu terasa lebih aman","Jelaskan bahwa data di pengelola sandi tepercaya dienkripsi kuat & dilindungi satu kata sandi utama yang sangat kuat, jauh lebih aman daripada memakai sandi lemah berulang di mana-mana","Abaikan kekhawatiran mereka dan pakai pengelola sandi diam-diam tanpa menjelaskan, karena orang tua biasanya tidak paham teknologi dan tidak perlu diberi tahu"],answer:1,explain:"Kekhawatiran yang wajar layak dijawab dengan penjelasan, bukan diabaikan atau langsung menyerah. Ini juga melatih menjelaskan konsep teknis dengan sopan.",hint:"Jelaskan dengan hormat & informasi, atau abaikan / menyerah?"},
{n:90,type:"order",micro:"Proyek: bersihkan & amankan akun",q:"Urutkan langkah proyek 'audit & perkuat keamanan akun' selama satu minggu.",items:["Hari 1-2: buat daftar semua akun & catat mana yang sandinya dipakai ulang","Hari 3-4: ganti kata sandi akun berisiko tinggi (dipakai ulang + penting) satu per satu dengan sandi unik","Hari 5: nyalakan 2FA untuk akun-akun paling penting yang mendukungnya","Hari 6-7: perbarui info pemulihan (email/nomor) & simpan kode cadangan di tempat aman"],answer:[0,1,2,3],explain:"Daftar & identifikasi risiko → perbaiki sandi berisiko tinggi dulu → tambah lapisan 2FA → pastikan jalur pemulihan siap. Prioritas dari risiko terbesar ke penguatan tambahan.",hint:"Mengganti kata sandi berisiko tinggi sebelum atau sesudah menyalakan 2FA?"},
{n:91,type:"mcq",micro:"Skenario: menyeimbangkan cepat vs benar saat darurat",q:"Kamu curiga akun pentingmu sedang diakses orang lain SAAT INI. Tindakan pertama yang paling penting:",options:["Tunggu sampai benar-benar yakin dulu baru bertindak, sambil memantau akunmu dari waktu ke waktu","Unggah kecurigaanmu di media sosial dulu supaya banyak orang tahu, baru pikirkan langkah mengamankan akun","Segera ganti kata sandi dari perangkat yang kamu percaya aman, sebelum melakukan hal lain"],answer:2,explain:"Mengunci pintu dulu (ganti sandi) menghentikan akses yang sedang berlangsung. Investigasi & pemberitahuan bisa menyusul.",hint:"Ganti kata sandi segera, atau menunggu yakin / mengumumkan dulu?"},
{n:92,type:"tf",micro:"Semua orang bisa jadi target",q:"Benar atau Salah: Bukan hanya orang 'penting' atau 'terkenal' yang bisa jadi target pembobolan akun; siapa pun dengan akun daring bisa jadi sasaran, sering lewat serangan otomatis massal, bukan serangan yang menargetkan orang tertentu.",answer:true,explain:"Banyak serangan bersifat otomatis & mencoba jutaan akun sekaligus, bukan memilih 'korban penting' secara khusus. Semua orang layak berhati-hati.",hint:"Siapa pun bisa jadi target, atau hanya orang terkenal?"},
{n:93,type:"mcq",micro:"Skenario: 2FA lewat SMS vs aplikasi",q:"Kamu diberi pilihan 2FA lewat SMS atau lewat aplikasi autentikasi. Pertimbangan yang relevan:",options:["Aplikasi autentikasi umumnya sedikit lebih aman (SMS bisa disadap lewat trik tertentu), tapi SMS tetap jauh lebih baik daripada tanpa 2FA sama sekali","SMS selalu 100% tidak aman dan harus dihindari mutlak, jadi lebih baik tidak memakai 2FA sama sekali kalau hanya pilihannya lewat SMS","Keduanya benar-benar sama persis, tidak ada bedanya sama sekali dalam keamanan, dan pilihan mana pun tidak perlu dipertimbangkan oleh siapa pun"],answer:0,explain:"Ada perbedaan tingkat keamanan, tapi memilih SMS tetap jauh lebih baik daripada tidak memakai 2FA sama sekali. Jangan sampai 'takut kurang sempurna' membuat tidak memakai apa pun.",hint:"Aplikasi sedikit lebih baik tapi SMS tetap jauh lebih baik dari tanpa 2FA, atau SMS harus dihindari total?"},
{n:94,type:"mcq",micro:"Skenario: menemukan sandi tertulis di buku teman",q:"Kamu tidak sengaja melihat teman sekelas menulis kata sandinya di buku catatan yang terbuka. Sikap yang baik:",options:["Beri tahu banyak orang di kelas bahwa dia menulis sandinya di buku terbuka, supaya semua ikut mengingatkannya","Beri tahu dia secara pribadi bahwa itu berisiko & sarankan menutupinya/menyimpan lebih aman, tanpa mempermalukan atau memakai info itu","Diam-diam mencatat sandinya untuk iseng nanti, karena itu bercanda dan tidak merugikan asal tidak dipakai sungguhan"],answer:1,explain:"Kesempatan untuk membantu dengan baik, bukan untuk mengeksploitasi atau mempermalukan. Ini juga menunjukkan integritas pribadi.",hint:"Beri tahu baik-baik secara pribadi, atau manfaatkan / permalukan?"},
{n:95,type:"tf",micro:"Keamanan akun adalah keterampilan seumur hidup",q:"Benar atau Salah: Prinsip dasar menjaga kata sandi & akun (unik, kuat, 2FA, waspada phishing, jaga kerahasiaan) akan terus relevan seiring bertambahnya akun & tanggung jawab digital sepanjang hidup.",answer:true,explain:"Teknologi berubah, tapi prinsip dasar ini (keunikan, kekuatan, lapisan tambahan, kewaspadaan) tetap jadi fondasi keamanan digital di masa depan.",hint:"Tetap relevan seumur hidup, atau hanya penting saat sekolah?"},
{n:96,type:"mcq",micro:"Skenario: menyeimbangkan banyak akun baru",q:"Kamu baru saja harus membuat 5 akun baru untuk keperluan sekolah dalam sehari. Cara mengelola dengan bijak:",options:["Pakai satu sandi sederhana yang sama untuk kelima akun supaya cepat selesai dan tidak perlu menyimpannya di tempat tertentu secara khusus","Tunda membuat akun-akun itu sampai punya waktu yang sangat banyak, walau tugas sekolah harus segera dikerjakan dan guru menunggu hasilnya","Pakai pengelola kata sandi untuk membuatkan & menyimpan sandi unik untuk tiap akun, daripada tergesa memakai sandi yang sama demi cepat"],answer:2,explain:"Situasi terburu-buru adalah saat paling rawan membuat kebiasaan buruk (sandi sama untuk semua). Alat yang tepat membuat cara aman tetap cepat.",hint:"Pakai pengelola sandi untuk tetap unik & cepat, atau satu sandi sama / tunda?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami keamanan kata sandi & akun:",options:["Kamu bisa membuat sandi kuat sendiri, tahu kapan & kenapa memakai 2FA, mengenali tanda phishing, & tahu langkah saat akun bermasalah","Kamu hafal definisi 'phishing' dengan sangat baik, tetapi tetap mengklik tautan mencurigakan, dan tidak tahu apa yang harus dilakukan saat akun bermasalah","Kamu punya satu sandi yang sangat panjang dan dipakai untuk semua akun, sehingga merasa aman walau satu kebocoran membuka semuanya sekaligus"],answer:0,explain:"Pemahaman sejati terlihat dari tindakan nyata (membuat, memilih, mengenali, merespons), bukan hanya menghafal istilah.",hint:"Bisa bertindak nyata, atau hafal istilah tanpa bertindak / satu sandi untuk semua?"},
{n:98,type:"mcq",micro:"Keamanan akun & orang lain",q:"Menjaga akunmu sendiri tetap aman juga melindungi orang lain karena...",options:["Hanya melindungi dirimu sendiri, karena akunmu tidak berhubungan dengan teman atau keluarga yang tersambung","Akun yang diretas sering dipakai menipu kontak-kontaknya (teman, keluarga) yang mempercayai pesan darimu","Tidak berhubungan dengan orang lain, sebab pesan dari akun yang diretas langsung dikenali sebagai penipuan oleh kontakmu"],answer:1,explain:"Keamanan digital punya efek berantai. Akunmu yang aman berarti orang di sekitarmu juga lebih terlindungi dari penipuan yang mengatasnamakanmu.",hint:"Melindungi kontak-kontak juga, atau hanya dirimu?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'kata sandi & akun aman':",options:["Menghafal satu kata sandi terpanjang yang bisa dibuat dan memakainya di semua akun tanpa 2FA, tanpa perlu waspada terhadap penipuan atau tahu langkah saat bermasalah","Menghindari membuat akun sama sekali selama mungkin, sehingga tidak perlu kata sandi, tidak perlu 2FA, dan tidak perlu belajar apa pun tentang keamanan digital","Buat kata sandi kuat & unik per akun, tambahkan lapisan seperti 2FA, jaga kerahasiaannya, waspada penipuan, & tahu langkah cepat saat ada masalah"],answer:2,explain:"Kuat + unik + lapisan tambahan + rahasia + waspada + siap bertindak. Kombinasi kebiasaan ini melindungi identitas digital secara menyeluruh.",hint:"Kombinasi kebiasaan menyeluruh, atau satu sandi super panjang / hindari akun?"},
{n:100,type:"open",micro:"Kapstone: sistem keamanan akun pribadi",q:"Rancang 'sistem keamanan akun' pribadimu untuk diterapkan mulai sekarang. Sertakan: (a) cara kamu akan membuat & mengingat kata sandi (teknik + alat), (b) aturan pribadi tentang kapan & dengan siapa kamu (tidak) akan berbagi info akun, (c) daftar periksa 2FA & pemulihan yang akan kamu terapkan ke akun-akun pentingmu, (d) langkah tepat yang akan kamu ambil bila mencurigai sebuah akun diretas, (e) bagaimana kamu akan mengecek & memperbarui sistem ini secara berkala.",explain:"Jawaban baik: metode konkret untuk membuat & mengelola sandi (bukan sekadar 'akan membuat yang kuat'), aturan berbagi yang jelas & realistis (termasuk konteks keluarga), daftar periksa 2FA/pemulihan yang spesifik untuk akun bernama, langkah respons darurat yang berurutan & benar, & jadwal peninjauan berkala yang konkret (bukan 'akan sering mengecek').",hint:"Bagian (e) sering dilewati, tapi penting, sistem keamanan yang baik selalu punya jadwal peninjauan, bukan 'atur sekali lalu lupakan'.",sample:"(a) Membuat & mengingat: aku akan pakai teknik kalimat/frasa acak untuk 3-4 sandi 'kunci utama' (email, pengelola sandi, akun sekolah, media sosial utama) yang kuhafal sendiri, & memakai pengelola kata sandi untuk membuat & menyimpan sandi acak panjang untuk akun-akun lainnya. (b) Aturan berbagi: aku tidak akan pernah membagikan kata sandi ke teman atau siapa pun di luar keluarga inti, kecuali dalam keadaan darurat yang jelas & akan segera kuganti setelahnya; untuk orang tua, aku terbuka mendiskusikan akses ke akun tertentu untuk keperluan pengawasan yang wajar, dengan syarat dibicarakan dulu, bukan diam-diam. (c) Daftar periksa: untuk email utama, media sosial utama, & akun sekolah, aku akan memastikan (1) kata sandinya unik & kuat, (2) 2FA aktif kalau tersedia (prioritas aplikasi autentikasi, SMS sebagai cadangan), (3) email/nomor pemulihan benar & aktif, (4) kode cadangan disimpan di tempat terpisah dari HP utama. (d) Bila mencurigai diretas: segera ganti kata sandi akun itu dari perangkat yang kupercaya, cek & keluarkan sesi/perangkat asing yang login, nyalakan 2FA bila belum, beri tahu kontak dekat bila ada aktivitas aneh atas namaku, & catat kejadiannya sebagai pelajaran. (e) Mengecek & memperbarui: setiap 3 bulan aku akan meluangkan 15 menit untuk meninjau daftar akun pentingku, memeriksa apakah masih ada sandi yang dipakai ulang, memastikan info pemulihan masih aktif (terutama kalau nomor HP-ku berganti), & mengecek apakah ada kabar kebocoran data dari layanan yang kupakai."},
];
